import{z as n,x as B,o as s,c as d,q as r,j as o,D as t,d as e,s as l,S as A,b as E}from"./chunks/framework.C8m1ZpeB.js";const _=JSON.parse('{"title":"统计信息","description":"","frontmatter":{"title":"统计信息","date":"2026-09-18T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/qo-statistics.md","filePath":"cs/qo-statistics.md","lastUpdated":1791063341000}'),p={name:"cs/qo-statistics.md"};function c(h,a,m,u,D,f){const i=B("Mermaid");return s(),d("div",null,[a[2]||(a[2]=r('<h1 id="统计信息" tabindex="-1">统计信息 <a class="header-anchor" href="#统计信息" aria-label="Permalink to &quot;统计信息&quot;">​</a></h1><div class="epigraph"><p>优化器读的从来不是表，而是关于表的摘要；摘要过期，后面的枚举与实现只是在精致的错误上做选择。</p><footer>—— 据 Poosala et al., 1996；Ioannidis and Christodoulakis, 1991；PostgreSQL 对 ANALYZE 的口径整理</footer></div><p><a href="/cs/qo-join-implementation">上一课</a>把哈希连接的常数钉在缓存与倾斜上，但「哪侧当 build」仍由估计决定。主干 <a href="/cs/cardinality-error-propagation">基数估计误差传播</a> 讲了误差怎么沿树放大，<a href="/cs/db-sampling-sketches">采样与草图统计</a> 讲了摘要怎么采出来。本课把统计信息当一套要运维的子系统：目录里存什么、何时过期、谁来刷新、刷新怎么联动计划缓存。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>目录摘要通常包括：行数与页数、每列不同值个数、NULL 比例、最频繁值及其频率、<span class="marginnote">直方图就是把一列的取值范围切成若干桶、数出每桶里有多少行的小抄——优化器问「年龄在 30 到 40 之间占多少行」时不用扫表，直接查对应桶的行数占比即可。</span><a href="/cs/histogram-card">直方图</a>、列间相关性或函数依赖、部分表达式统计。麻烦有四类。漂移：摘要是快照，批量写入后立刻开始过期，而「过期了多少」对外不可见。相关：城市与邮编独立假设谎报选择率，单列直方图无能为力。分区：分区表各有局部统计，全局谓词要合并估计，分区裁剪又要局部值——两套都要，还不能互相撒谎。成本：收集本身是全表采样，不能每写一笔就跑。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>触发策略：<span class="marginnote">数字实例：一张一百万行的表，阈值「50 行加行数的十分之一」即 \\(50 + 100000 = 100050\\) 行——所以一次导入九万行的更新不会触发自动收集，摘要照旧过期；这就是「批量导入后必须手动 ANALYZE」这条经验背后的算术。</span>变更行数超过阈值（常数加比例，如「50 行加表行数的十分之一」）触发自动收集；大表给更大容差，高频小表给更紧的目标。列组统计：对负载里反复出现的联合谓词维护联合不同值个数与联合最频繁值；函数依赖显式声明（邮编决定城市），优化器把两个条件当一条算。表达式统计：对 <code>date(ts)</code> 这类包装列建虚拟列统计，否则优化器对函数返回值的分布一无所知。分区口径：不同值个数用可合并草图——各分区一份合并成全局；直方图分区各自维护，全局估计用分位数合并。草图课讲过的可合并性在这里兑现。</p>',7)),(s(),o(A,null,{default:t(()=>[l(i,{id:"mermaid-19",class:"mermaid",graph:"flowchart%20TD%0A%20%20DML%5B%22%E5%86%99%E5%85%A5%E6%B5%81%22%5D%20--%3E%20TRIG%5B%22%E5%8F%98%E6%9B%B4%E8%B6%85%E9%98%88%E5%80%BC%E8%A7%A6%E5%8F%91%22%5D%0A%20%20TRIG%20--%3E%20SMP%5B%22%E9%87%87%E6%A0%B7%20%2F%20%E8%8D%89%E5%9B%BE%22%5D%0A%20%20SMP%20--%3E%20CAT%5B%22%E7%9B%AE%E5%BD%95%EF%BC%9AMCV%20%2F%20%E7%9B%B4%E6%96%B9%E5%9B%BE%20%2F%20%E5%88%97%E7%BB%84%22%5D%0A%20%20CAT%20--%3E%20INV%5B%22%E8%AE%A1%E5%88%92%E5%A4%B1%E6%95%88%E6%A0%87%E8%AE%B0%22%5D%0A%20%20INV%20--%3E%20NEXT%5B%22%E4%B8%8B%E6%AC%A1%E6%9E%9A%E4%B8%BE%E8%AF%BB%E6%96%B0%E6%91%98%E8%A6%81%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[e(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E("h2",{id:"机制",tabindex:"-1"},[e("机制 "),E("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=E("p",null,[e("统计与计划缓存联动是硬要求：摘要刷新后，依赖旧摘要的计划要失效或标记再优化，否则新统计永远没有用户——"),E("a",{href:"/cs/prepared-plan-cache"},"计划缓存"),e("课已立此合同。收集在后台事务里跑，与用户写入隔离，代价要可限流；让统计刷新拖垮写负载是常见的运维事故。粒度是双刃：分区级统计准但贵且难合并，全局统计便宜但掩盖倾斜——热点分区的倾斜必须在局部统计里可见。低估仍是最危险的方向：下游连接会因此选错 build 侧、选嵌套循环去打大表，误差传播课已经算过这笔账。")],-1)),a[5]||(a[5]=E("p",null,[E("span",{class:"marginnote"},"PostgreSQL 默认统计目标是一百个桶；自动收集在变更超过「50 行加表行数的十分之一」时触发，可对单表单列收紧目标。这两个默认值解释了「批量导入后必须手动 ANALYZE」的常见经验。")],-1)),(s(),o(A,null,{default:t(()=>[l(i,{id:"mermaid-29",class:"mermaid",graph:"flowchart%20TD%0A%20%20OLD%5B%22%E6%91%98%E8%A6%81%E8%BF%87%E6%9C%9F%EF%BC%9A%E5%AF%BC%E5%85%A5%E5%90%8E%E6%9C%AA%E5%88%B7%E6%96%B0%22%5D%20--%3E%20UNDER%5B%22%E4%BC%B0%E8%AE%A1%E8%A1%8C%E6%95%B0%E5%81%8F%E5%B0%8F%22%5D%0A%20%20UNDER%20--%3E%20Q%7B%22%E8%BF%9E%E6%8E%A5%E9%80%89%E5%9E%8B%E5%88%A4%E6%96%AD%22%7D%0A%20%20Q%20--%3E%7C%E4%BB%A5%E4%B8%BA%E5%A4%96%E8%A1%A8%E5%BE%88%E5%B0%8F%7C%20NL%5B%22%E9%80%89%E5%B5%8C%E5%A5%97%E5%BE%AA%E7%8E%AF%E5%8F%8D%E5%A4%8D%E6%89%93%E5%A4%A7%E8%A1%A8%22%5D%0A%20%20Q%20--%3E%7Cbuild%20%E4%BE%A7%E9%80%89%E5%B0%8F%7C%20WRONG%5B%22build%20%E4%BE%A7%E9%80%89%E9%94%99%22%5D%0A%20%20WRONG%20--%3E%20SPILL%5B%22%E5%93%88%E5%B8%8C%E8%A1%A8%E6%BA%A2%E5%87%BA%E7%A3%81%E7%9B%98%22%5D%0A%20%20NL%20--%3E%20SLOW%5B%22%E6%89%A7%E8%A1%8C%E6%85%A2%E4%B8%80%E5%88%B0%E4%B8%A4%E4%B8%AA%E9%87%8F%E7%BA%A7%22%5D%0A%20%20SPILL%20--%3E%20SLOW%0A"})]),fallback:t(()=>[...a[1]||(a[1]=[e(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=r('<p><span class="marginnote">初学者容易以为统计越新越好、最好每次写入都刷新；实际上收集是全表采样，每写一笔就跑会把写负载拖垮——工程上用「变更超阈值才刷新」在新鲜度与开销之间取平衡。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>运行时的动态采样归自适应执行课；学习型基数估计是主干已点名的插件，不改变本课的存储与触发结构。直方图选择率的积分公式主干直方图课已给，本课不重推。统计的质量上限就是采样的质量：极低选择率谓词在样本里可能零命中，平滑与索引统计兜底——采样课的边界再次成立。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>摘要是快照：阈值触发的自动收集是工程底线，不是可选项。</li><li>相关列要列组统计或函数依赖；独立假设默认在说谎。</li><li>分区表局部与全局统计两套都要，草图负责合并。</li><li>刷新必须联动计划失效，否则新统计无人受益。</li><li>出处：Poosala et al., 1996；Ioannidis and Christodoulakis, 1991；PostgreSQL 文档。</li></ul>',5))])}const P=n(p,[["render",c]]);export{_ as __pageData,P as default};
